/* =========================================================
   PRÍKAZOVÝ DRIL – rozšírenie (druhá sada)
   match: regulárny výraz pre odpovede, ktoré sa nespúšťajú
          v shelli (klávesy vo vim)
   ver:   verzia stroja (predvolene 9)
   ========================================================= */
(function(){
const L = (m,n)=>m.log.filter(e=>e.name===n);
const ran = (m,n,flags=[],pred)=>L(m,n).some(e=>e.code===0 && flags.every(f=>e.flags.has(f)) && (!pred||pred(e)));
const any = (m,n,pred)=>L(m,n).some(e=>e.code===0 && (!pred||pred(e)));
const arg = (e,re)=>e.args.some(a=>re.test(a));
const root = e=>e.user==='root';
const asRoot = (m,cmds)=>{ const p=m.user; m.user='root'; try { cmds.forEach(c=>m.run(' '+c)); } finally { m.user=p; } };
const H = '/home/admin';
const txt = (m,p)=>m.read(p)||'';
const V = (id,q,a,w,re)=>({id, ch:5, q, a, w, match:re});

window.DRILL.push(
/* ---------- 1 terminál a pomoc ---------- */
{id:'man1', ch:1, q:'Otvor manuálovú stránku príkazu <code>ls</code>.', a:'man ls', w:'V man: / hľadá, n ďalší výskyt, q koniec.', check:m=>any(m,'man',e=>arg(e,/^ls$/))},
{id:'hist', ch:1, q:'Zobraz históriu príkazov, ktoré si zadal.', a:'history', w:'!123 zopakuje príkaz č. 123, Ctrl+R hľadá v histórii.', check:m=>any(m,'history')},
{id:'which', ch:1, q:'Zisti, ktorý súbor sa spustí, keď napíšeš <code>systemctl</code>.', a:'which systemctl', w:'Alebo type systemctl (ukáže aj aliasy a vstavané príkazy).', check:m=>any(m,'which',e=>arg(e,/systemctl/)) || any(m,'type',e=>arg(e,/systemctl/))},
{id:'whoami', ch:1, q:'Zisti, pod akým používateľom si prihlásený.', a:'whoami', w:'id ukáže aj UID a skupiny.', check:m=>any(m,'whoami') || any(m,'id')},
{id:'unr', ch:1, q:'Zisti verziu bežiaceho jadra.', a:'uname -r', w:'-r release jadra, -a všetko.', check:m=>ran(m,'uname',['r']) || ran(m,'uname',['a'])},
{id:'rel', ch:1, q:'Zisti presnú verziu RHEL (súbor v /etc).', a:'cat /etc/redhat-release', w:'Podrobnejšie: cat /etc/os-release.', check:m=>any(m,'cat',e=>arg(e,/redhat-release|os-release/))},
{id:'hn', ch:1, q:'Zisti meno servera (hostname) a verziu OS jedným príkazom.', a:'hostnamectl', w:'hostnamectl ukáže hostname, OS, jadro aj virtualizáciu.', check:m=>any(m,'hostnamectl')},
{id:'clr', ch:1, q:'Vyčisti obrazovku terminálu.', a:'clear', w:'Skratka: Ctrl+L.', check:m=>any(m,'clear')},

/* ---------- 2 súbory a adresáre ---------- */
{id:'cd1', ch:2, q:'Prejdi do adresára <code>/etc</code>.', a:'cd /etc', w:'cd bez argumentu ťa vráti domov.', check:m=>m.cwd==='/etc'},
{id:'cdh', ch:2, q:'Si v <code>/tmp</code>. Vráť sa najkratším spôsobom do domovského adresára.', a:'cd', w:'cd alebo cd ~. cd - skočí do predošlého adresára.', setup:m=>m.run('cd /tmp'), check:m=>m.cwd===H},
{id:'cdp', ch:2, q:'Si v <code>/etc/ssh</code>. Prejdi o úroveň vyššie.', a:'cd ..', w:'.. je nadradený adresár, . aktuálny.', setup:m=>m.run('cd /etc/ssh'), check:m=>m.cwd==='/etc'},
{id:'touch', ch:2, q:'Vytvor prázdny súbor <code>~/novy.txt</code>.', a:'touch ~/novy.txt', w:'touch na existujúcom súbore len zmení čas.', check:m=>m.isFile(H+'/novy.txt')},
{id:'mv1', ch:2, q:'Premenuj <code>~/poznamky.txt</code> na <code>~/ulohy.txt</code>.', a:'mv ~/poznamky.txt ~/ulohy.txt', w:'Premenovanie je v Linuxe presun (mv).', check:m=>m.isFile(H+'/ulohy.txt') && !m.exists(H+'/poznamky.txt')},
{id:'mv2', ch:2, q:'Presuň <code>~/index.html</code> do adresára <code>/tmp</code>.', a:'mv ~/index.html /tmp/', w:'Ak cieľ je adresár, súbor si ponechá meno.', check:m=>m.isFile('/tmp/index.html') && !m.exists(H+'/index.html')},
{id:'rm1', ch:2, q:'Zmaž súbor <code>~/index.html</code>.', a:'rm ~/index.html', w:'V Linuxe nie je kôš. rm -i sa pýta.', check:m=>!m.exists(H+'/index.html') && m.isDir(H+'/data')},
{id:'rmr', ch:2, q:'Zmaž adresár <code>~/data</code> aj s obsahom.', a:'rm -r ~/data', w:'-r rekurzívne. Prázdny adresár zmaže aj rmdir.', check:m=>!m.exists(H+'/data') && m.isDir(H+'/logy')},
{id:'rmdir', ch:2, q:'Zmaž prázdny adresár <code>~/prazdny</code> príkazom, ktorý zmaže len prázdny adresár.', a:'rmdir ~/prazdny', w:'rmdir odmietne zmazať adresár s obsahom, čo je bezpečné.', setup:m=>m.run('mkdir ~/prazdny'), check:m=>!m.exists(H+'/prazdny') && ran(m,'rmdir')},
{id:'cpp', ch:2, q:'Sprav zálohu <code>/etc/hosts</code> do <code>~/hosts.bak</code> so zachovaním času a práv.', a:'cp -p /etc/hosts ~/hosts.bak', w:'-p zachová čas, práva a vlastníka (ak môžeš). -a robí to isté rekurzívne.', check:m=>m.isFile(H+'/hosts.bak') && (ran(m,'cp',['p']) || ran(m,'cp',['a']))},
{id:'lsd', ch:2, q:'Zobraz práva samotného adresára <code>/etc</code>, nie jeho obsah.', a:'ls -ld /etc', w:'-d vypíše adresár ako položku.', check:m=>ran(m,'ls',['d','l'],e=>arg(e,/^\/etc\/?$/))},
{id:'lsS', ch:2, q:'Vypíš <code>/var/log</code> zoradené podľa veľkosti (najväčší hore) s čitateľnými veľkosťami.', a:'ls -lhS /var/log', w:'-S podľa veľkosti, -r otočí poradie.', check:m=>ran(m,'ls',['S'],e=>arg(e,/var\/log/))},
{id:'mvi', ch:2, q:'Skopíruj <code>~/poznamky.txt</code> do <code>/tmp</code> tak, aby sa cp opýtal pred prepísaním existujúceho súboru.', a:'cp -i ~/poznamky.txt /tmp/', w:'-i = interaktívne. Platí aj pre mv a rm.', check:m=>ran(m,'cp',['i']) && m.isFile('/tmp/poznamky.txt')},

/* ---------- 3 kde čo je (FHS) ---------- */
{id:'fhs1', ch:3, q:'Vypíš súbory s definíciami repozitárov dnf.', a:'ls /etc/yum.repos.d/', w:'Repozitáre sú v /etc/yum.repos.d/*.repo.', check:m=>any(m,'ls',e=>arg(e,/yum\.repos\.d/))},
{id:'fhs2', ch:3, q:'Zobraz informácie o OS v štandardnom súbore, ktorý čítajú skripty aj Ansible.', a:'cat /etc/os-release', w:'NAME, VERSION_ID, ID… Napr. VERSION_ID="9.6".', check:m=>any(m,'cat',e=>arg(e,/os-release/))},
{id:'fhs3', ch:3, q:'Vypíš vlastné unit súbory, ktoré vytvoril administrátor.', a:'ls /etc/systemd/system/', w:'/etc/systemd/system má prednosť pred /usr/lib/systemd/system (balíky).', check:m=>any(m,'ls',e=>arg(e,/^\/etc\/systemd\/system\/?$/))},
{id:'fhs4', ch:3, q:'Zisti, kam ukazuje <code>/bin</code>.', a:'ls -l /bin', w:'Na RHEL 9 je /bin odkaz na usr/bin (usrmerge).', check:m=>ran(m,'ls',['l'],e=>arg(e,/^\/bin\/?$/)) || any(m,'readlink',e=>arg(e,/bin/))},
{id:'fhs5', ch:3, q:'Zobraz konfiguráciu produktu tretej strany nainštalovaného v <code>/opt/monitoring</code> (súbor <code>agent.conf</code>).', a:'cat /opt/monitoring/agent.conf', w:'Produkty mimo RPM žijú v /opt/NÁZOV.', check:m=>any(m,'cat',e=>arg(e,/opt\/monitoring\/agent\.conf/)) || any(m,'less',e=>arg(e,/agent\.conf/))},
{id:'fhs6', ch:3, q:'Skopíruj svoj skript <code>~/skripty/kontrola.sh</code> tam, kam patria lokálne programy administrátora.', a:'sudo cp ~/skripty/kontrola.sh /usr/local/bin/', w:'/usr/local/bin je v PATH a balíky ho neprepíšu.', check:m=>m.isFile('/usr/local/bin/kontrola.sh')},
{id:'fhs7', ch:3, q:'Zobraz posledné záznamy hlavného systémového logu <code>/var/log/messages</code>.', a:'sudo tail /var/log/messages', w:'Súbor je čitateľný len pre roota. Alternatíva: journalctl.', check:m=>any(m,'tail',e=>arg(e,/var\/log\/messages/)) || any(m,'less',e=>arg(e,/messages/))},
{id:'fhs8', ch:3, q:'Zobraz, ktoré súborové systémy sú pripojené a kam, v prehľadnom strome.', a:'findmnt', w:'findmnt je čitateľnejší ako mount bez parametrov.', check:m=>any(m,'findmnt') || any(m,'mount',e=>!e.args.length)},

/* ---------- 4 čítanie a hľadanie ---------- */
{id:'head', ch:4, q:'Zobraz prvých 5 riadkov <code>/etc/passwd</code>.', a:'head -n 5 /etc/passwd', w:'head -n N (alebo head -5).', check:m=>any(m,'head',e=>(e.args.includes('5')||e.args.includes('-5')||e.args.includes('-n5')) && arg(e,/passwd/))},
{id:'tailf', ch:4, q:'Sleduj <code>~/logy/app.log</code> naživo (nové riadky sa budú vypisovať).', a:'tail -f ~/logy/app.log', w:'-f follow, ukončíš Ctrl+C. -F prežije aj rotáciu logu.', check:m=>L(m,'tail').some(e=>(e.flags.has('f')||e.flags.has('F')) && arg(e,/app\.log/))},
{id:'wcl', ch:4, q:'Spočítaj riadky v <code>~/data/servery.csv</code>.', a:'wc -l ~/data/servery.csv', w:'-l riadky, -w slová, -c bajty.', check:m=>ran(m,'wc',['l'],e=>arg(e,/servery\.csv/)) || (any(m,'cat',e=>arg(e,/servery/)) && ran(m,'wc',['l']))},
{id:'gE', ch:4, q:'Vypíš z <code>~/logy/app.log</code> riadky s <code>ERROR</code> alebo <code>WARN</code> jedným grepom.', a:'grep -E "ERROR|WARN" ~/logy/app.log', w:'-E rozšírené regexy, | znamená alebo. Ide aj grep -e ERROR -e WARN.', check:m=>ran(m,'grep',['E'],e=>arg(e,/ERROR\|WARN|WARN\|ERROR/)) || L(m,'grep').some(e=>e.code===0 && e.args.filter(a=>a==='-e').length>=2) || any(m,'egrep')},
{id:'gl', ch:4, q:'Vypíš len <b>mená súborov</b> v <code>/etc</code> (rekurzívne), ktoré obsahujú text <code>10.0.20.2</code>.', a:'sudo grep -rl 10.0.20.2 /etc', w:'-l vypíše len mená súborov, -r rekurzívne.', check:m=>ran(m,'grep',['r','l'],e=>arg(e,/10\.0\.20\.2/)) || ran(m,'grep',['R','l'],e=>arg(e,/10\.0\.20\.2/))},
{id:'gw', ch:4, q:'Nájdi v <code>~/data/prihlasenia.txt</code> riadky s celým slovom <code>jana</code> (nie napr. „janak“).', a:'grep -w jana ~/data/prihlasenia.txt', w:'-w hľadá celé slová.', check:m=>ran(m,'grep',['w'],e=>arg(e,/^jana$/))},
{id:'gA', ch:4, q:'Nájdi v <code>~/logy/app.log</code> riadky s <code>ERROR</code> a ku každému zobraz aj 2 nasledujúce riadky.', a:'grep -A 2 ERROR ~/logy/app.log', w:'-A after, -B before, -C okolo.', check:m=>L(m,'grep').some(e=>e.code===0 && arg(e,/ERROR/) && (e.flags.has('A') || arg(e,/^-A\d/)))},
{id:'fu', ch:4, q:'Nájdi v <code>/home</code> všetky súbory, ktoré vlastní používateľ <code>admin</code>.', a:'find /home -user admin', w:'-user meno, -group skupina.', check:m=>L(m,'find').some(e=>arg(e,/^\/home\/?$/) && e.args.includes('-user') && arg(e,/^admin$/))},
{id:'ftd', ch:4, q:'Nájdi v <code>/etc</code> len adresáre s menom <code>ssh</code>.', a:'find /etc -type d -name ssh', w:'-type d adresár, f súbor, l odkaz.', check:m=>L(m,'find').some(e=>arg(e,/^\/etc\/?$/) && e.args.includes('-type') && e.args.includes('d') && e.args.includes('-name'))},
{id:'fin', ch:4, q:'Nájdi v domovskom adresári súbory s menom končiacim na <code>.sh</code> bez ohľadu na veľkosť písmen.', a:'find ~ -iname "*.sh"', w:'-iname ignoruje veľkosť písmen.', check:m=>L(m,'find').some(e=>e.args.includes('-iname') && arg(e,/\*\.sh/i))},
{id:'fex', ch:4, q:'Nájdi v <code>/tmp</code> súbory s príponou <code>.log</code> a rovno ich zmaž (jedným find).', a:'find /tmp -name "*.log" -delete', w:'Najprv vždy spusti bez -delete a pozri, čo nájde. Alternatíva: -exec rm {} \\;', setup:m=>{ m.run('touch /tmp/a.log /tmp/b.log /tmp/c.txt'); }, check:m=>!m.exists('/tmp/a.log') && !m.exists('/tmp/b.log') && m.exists('/tmp/c.txt')},

/* ---------- 5 vim (klávesy) ---------- */
V('vwq','Vo vim si v normálnom režime. Ulož súbor a zavri ho.',':wq','Alebo :x či ZZ. :w len uloží.',/^(:wq!?|:x!?|ZZ)$/),
V('vq','Vo vim chceš odísť <b>bez uloženia</b> zmien.',':q!','! = vynúť. Samotné :q pri zmenách odmietne.',/^:q!$/),
V('vdd','Vo vim zmaž celý riadok, na ktorom stojí kurzor.','dd','dd vystrihne riadok, p ho vloží.',/^dd$/),
V('v3dd','Vo vim zmaž 3 riadky naraz.','3dd','Číslo pred príkazom = počet opakovaní.',/^(3dd|d2j|d3d)$/),
V('vu','Vo vim vráť poslednú zmenu (undo).','u','Ctrl+r urobí redo.',/^u$/),
V('vG','Vo vim skoč na koniec súboru.','G','gg skočí na začiatok.',/^G$/),
V('vgg','Vo vim skoč na prvý riadok súboru.','gg','Alebo :1 alebo 1G.',/^(gg|1G|:1)$/),
V('v25','Vo vim skoč na riadok 25.',':25','Alebo 25G.',/^(:25|25G|25gg)$/),
V('vsr','Vo vim vyhľadaj dopredu slovo <code>Listen</code>.','/Listen','n = ďalší výskyt, N = predošlý. ? hľadá dozadu.',/^\/Listen$/),
V('vsub','Vo vim nahraď v celom súbore všetky výskyty <code>8080</code> za <code>8081</code>.',':%s/8080/8081/g','% = celý súbor, g = všetky výskyty v riadku, c na konci = pýtaj sa.',/^:%s\/8080\/8081\/g$/),
V('vyy','Vo vim skopíruj aktuálny riadok a vlož ho pod neho.','yyp','yy kopíruje (yank) riadok, p vloží pod.',/^yyp$/),
V('vnu','Vo vim zapni čísla riadkov.',':set nu','Vypnutie: :set nonu.',/^:set (nu|number)$/),
V('vA','Vo vim prejdi do vkladania na <b>koniec</b> aktuálneho riadku.','A','i pred kurzorom, a za kurzorom, A koniec riadku, I začiatok.',/^A$/),
V('vo','Vo vim vlož nový prázdny riadok <b>pod</b> aktuálny a začni písať.','o','O vloží riadok nad.',/^o$/),
V('vdw','Vo vim zmaž slovo od kurzora.','dw','Operátor d + pohyb w.',/^(dw|de)$/),
V('vesc','Píšeš text vo vim (INSERT). Ktorou klávesou sa vrátiš do normálneho režimu?','Esc','Esc, alebo Ctrl+[ ak Esc nemáš po ruke.',/^(esc|escape|ctrl\+\[|<esc>)$/i),

/* ---------- 6 rúry a presmerovanie ---------- */
{id:'rdr1', ch:6, q:'Ulož výstup príkazu <code>date</code> do súboru <code>~/cas.txt</code> (prepíše ho).', a:'date > ~/cas.txt', w:'> prepíše, >> pripojí na koniec.', check:m=>/\d{4}|2026/.test(txt(m,H+'/cas.txt'))},
{id:'rdr2', ch:6, q:'Pripoj na koniec <code>~/poznamky.txt</code> riadok <code>- zálohy hotové</code> (pôvodný obsah musí ostať).', a:'echo "- zálohy hotové" >> ~/poznamky.txt', w:'>> pripája. Jedno > by súbor prepísalo.', check:m=>/zálohy hotové\s*$/.test(txt(m,H+'/poznamky.txt')) && /Úlohy na tento týždeň/.test(txt(m,H+'/poznamky.txt'))},
{id:'rdr3', ch:6, q:'Spusti <code>find /etc -name "*.conf"</code> ako admin a chybové hlásenia (Permission denied) zahoď.', a:'find /etc -name "*.conf" 2>/dev/null', w:'2> presmeruje stderr. /dev/null všetko zahodí.', check:m=>L(m,'find').some(e=>arg(e,/\*\.conf/)) && m.history.some(h=>/2>\s*\/dev\/null/.test(h))},
{id:'rdr4', ch:6, q:'Ulož do <code>~/vystup.txt</code> výstup aj chyby príkazu <code>ls /etc /neexistuje</code>.', a:'ls /etc /neexistuje > ~/vystup.txt 2>&1', w:'2>&1 pošle chyby tam, kam ide výstup. Poradie je dôležité. Skrátene: &> súbor.', check:m=>/neexistuje/.test(txt(m,H+'/vystup.txt')) && /hosts/.test(txt(m,H+'/vystup.txt'))},
{id:'psg', ch:6, q:'Vypíš len procesy, v ktorých sa vyskytuje <code>sshd</code> (ps a grep).', a:'ps aux | grep sshd', w:'Lepšie: pgrep -a sshd (nevypíše samotný grep).', check:m=>(any(m,'ps') && any(m,'grep',e=>arg(e,/sshd/))) || any(m,'pgrep',e=>arg(e,/sshd/))},
{id:'srt', ch:6, q:'Vypíš <code>~/data/prihlasenia.txt</code> zoradené a bez duplicít.', a:'sort -u ~/data/prihlasenia.txt', w:'sort -u = sort | uniq.', check:m=>ran(m,'sort',['u']) || (any(m,'sort') && any(m,'uniq'))},
{id:'srtn', ch:6, q:'Zisti, ktoré meno sa v <code>~/data/prihlasenia.txt</code> vyskytuje najčastejšie (počty zoradené od najväčšieho).', a:'sort ~/data/prihlasenia.txt | uniq -c | sort -rn', w:'sort | uniq -c | sort -rn je klasika na „top N“. Pridaj | head -3.', check:m=>ran(m,'uniq',['c']) && L(m,'sort').some(e=>e.code===0 && e.flags.has('n') && e.flags.has('r'))},
{id:'awk1', ch:6, q:'Vypíš z <code>~/data/servery.csv</code> len druhý stĺpec (IP adresy). Oddeľovač je čiarka.', a:"awk -F, '{print $2}' ~/data/servery.csv", w:'Alebo cut -d, -f2 ~/data/servery.csv.', check:m=>any(m,'awk',e=>arg(e,/\$2/) && arg(e,/^-F,?$|^-F,$/)) || any(m,'cut',e=>arg(e,/^-d,?$/) && arg(e,/^(-f)?2$|^-f2$/))},
{id:'sedi', ch:6, q:'V súbore <code>~/poznamky.txt</code> nahraď (priamo v súbore) všetky <code>db01</code> za <code>db02</code>.', a:"sed -i 's/db01/db02/g' ~/poznamky.txt", w:'-i upraví súbor na mieste. Bez -i len vypíše výsledok.', check:m=>/db02/.test(txt(m,H+'/poznamky.txt')) && !/db01/.test(txt(m,H+'/poznamky.txt'))},
{id:'tr1', ch:6, q:'Vypíš <code>~/data/prihlasenia.txt</code> veľkými písmenami (pomocou rúry a <code>tr</code>).', a:"cat ~/data/prihlasenia.txt | tr a-z A-Z", w:"tr 'a-z' 'A-Z' alebo tr '[:lower:]' '[:upper:]'.", check:m=>any(m,'tr')},
{id:'xarg', ch:6, q:'Nájdi v <code>~/skripty</code> súbory <code>*.sh</code> a cez <code>xargs</code> ich všetky nastav ako spustiteľné.', a:'find ~/skripty -name "*.sh" | xargs chmod +x', w:'xargs zoberie riadky zo vstupu a dá ich ako argumenty príkazu.', check:m=>any(m,'xargs') && !!(m.node(H+'/skripty/zaloha.sh').m & 0o100) && !!(m.node(H+'/skripty/kontrola.sh').m & 0o100)},
{id:'teeo', ch:6, q:'Vypíš <code>df -h</code> na obrazovku a zároveň ho ulož do <code>~/disky.txt</code>.', a:'df -h | tee ~/disky.txt', w:'tee = T-kus: ide na obrazovku aj do súboru.', check:m=>any(m,'tee') && /Filesystem|Súborový/.test(txt(m,H+'/disky.txt'))},

/* ---------- 7 používatelia a sudo ---------- */
{id:'ga', ch:7, q:'Vytvor skupinu <code>vyvojari</code>.', a:'sudo groupadd vyvojari', w:'Členov pridáš cez usermod -aG.', check:m=>!!m.groups.vyvojari},
{id:'uag', ch:7, q:'Vytvor používateľa <code>marek</code> a rovno ho pridaj do skupiny <code>wheel</code>.', a:'sudo useradd -G wheel marek', w:'-G doplnkové skupiny pri vytvorení. wheel = smie sudo.', check:m=>!!m.users.marek && m.groups.wheel.mem.includes('marek')},
{id:'pw', ch:7, q:'Nastav heslo používateľovi <code>jana</code>.', a:'sudo passwd jana', w:'Bez mena mení heslo tebe.', setup:m=>asRoot(m,['useradd jana']), check:m=>m.users.jana && m.users.jana.pw},
{id:'udr', ch:7, q:'Zmaž používateľa <code>jana</code> aj s jej domovským adresárom.', a:'sudo userdel -r jana', w:'Bez -r ostane /home/jana.', setup:m=>asRoot(m,['useradd jana']), check:m=>!m.users.jana && !m.exists('/home/jana')},
{id:'nolog', ch:7, q:'Zmeň používateľovi <code>jana</code> shell tak, aby sa nemohol interaktívne prihlásiť.', a:'sudo usermod -s /sbin/nologin jana', w:'Pre servisné účty. /usr/sbin/nologin je to isté.', setup:m=>asRoot(m,['useradd jana']), check:m=>/nologin/.test(m.users.jana.shell)},
{id:'chM', ch:7, q:'Nastav, aby heslo používateľa <code>jana</code> platilo najviac 90 dní.', a:'sudo chage -M 90 jana', w:'-M max. dní, -E dátum expirácie účtu, -l výpis.', setup:m=>asRoot(m,['useradd jana']), check:m=>ran(m,'chage',['M'],e=>arg(e,/^90$|^-M90$/))},
{id:'gpd', ch:7, q:'Odober používateľa <code>admin</code> zo skupiny <code>adm</code> (ostatné skupiny nechaj).', a:'sudo gpasswd -d admin adm', w:'gpasswd -a pridá, -d odoberie.', setup:m=>asRoot(m,['usermod -aG adm admin']), check:m=>!m.groups.adm.mem.includes('admin') && m.groups.wheel.mem.includes('admin')},
{id:'sui', ch:7, q:'Získaj root shell cez sudo (s prostredím roota).', a:'sudo -i', w:'sudo -i = login shell roota. Návrat: exit.', check:m=>m.user==='root' || m.rootShell},
{id:'grps', ch:7, q:'Vypíš len mená skupín, v ktorých je používateľ <code>admin</code>.', a:'groups admin', w:'Alebo id -nG admin.', check:m=>any(m,'groups') || ran(m,'id',['n','G'])},
{id:'ugent', ch:7, q:'Vypíš riadok používateľa <code>admin</code> z databázy používateľov (ako ho vidí systém, vrátane LDAP/AD).', a:'getent passwd admin', w:'getent pozerá všetky zdroje z nsswitch.conf, nielen /etc/passwd.', check:m=>any(m,'getent',e=>e.args[0]==='passwd')},

/* ---------- 8 práva ---------- */
{id:'p755', ch:8, q:'Nastav adresáru <code>~/skripty</code> práva <code>rwxr-x---</code>.', a:'chmod 750 ~/skripty', w:'7 = rwx, 5 = r-x, 0 = nič. Pre adresár x znamená „smieš doň vojsť“.', check:m=>(m.node(H+'/skripty').m&0o777)===0o750},
{id:'p600', ch:8, q:'Nastav súboru <code>~/poznamky.txt</code> práva tak, aby ho mohol čítať a meniť <b>len vlastník</b>.', a:'chmod 600 ~/poznamky.txt', w:'Typicky pre súkromné kľúče a heslá.', check:m=>(m.node(H+'/poznamky.txt').m&0o777)===0o600},
{id:'pgw', ch:8, q:'Pridaj skupine právo zápisu na <code>~/poznamky.txt</code> (ostatné práva nemeň).', a:'chmod g+w ~/poznamky.txt', w:'Symbolicky: u/g/o/a, +/-/=, r/w/x.', check:m=>(m.node(H+'/poznamky.txt').m&0o777)===0o664},
{id:'por', ch:8, q:'Odober ostatným (others) všetky práva na <code>~/data</code> a všetko v ňom.', a:'chmod -R o-rwx ~/data', w:'-R rekurzívne.', check:m=>!(m.node(H+'/data').m&0o007) && !(m.node(H+'/data/servery.csv').m&0o007)},
{id:'chgrp', ch:8, q:'Zmeň skupinu súboru <code>~/poznamky.txt</code> na <code>wheel</code>.', a:'chgrp wheel ~/poznamky.txt', w:'Alebo chown :wheel súbor. Vlastník môže dať len skupinu, v ktorej je.', check:m=>m.node(H+'/poznamky.txt').g==='wheel'},
{id:'sgid', ch:8, q:'Nastav na adresári <code>/srv/tim</code> setgid, aby nové súbory dedili jeho skupinu.', a:'sudo chmod g+s /srv/tim', w:'V ls -l uvidíš s namiesto x pri skupine (drwxrwsr-x).', setup:m=>asRoot(m,['mkdir /srv/tim']), check:m=>!!(m.node('/srv/tim').m & 0o2000)},
{id:'stick', ch:8, q:'Nastav na adresári <code>/srv/zdielane</code> sticky bit (súbory zmaže len ich vlastník).', a:'sudo chmod +t /srv/zdielane', w:'Ako /tmp: drwxrwxrwt.', setup:m=>asRoot(m,['mkdir /srv/zdielane','chmod 777 /srv/zdielane']), check:m=>!!(m.node('/srv/zdielane').m & 0o1000)},
{id:'gfacl', ch:8, q:'Zobraz ACL súboru <code>~/poznamky.txt</code>.', a:'getfacl ~/poznamky.txt', w:'ACL poznáš podľa + na konci práv v ls -l.', check:m=>any(m,'getfacl')},
{id:'xacl', ch:8, q:'Odober ACL záznam používateľa <code>jana</code> zo súboru <code>~/poznamky.txt</code>.', a:'setfacl -x u:jana ~/poznamky.txt', w:'-x odoberie jeden záznam, -b všetky.', setup:m=>{ asRoot(m,['useradd jana']); m.run('setfacl -m u:jana:r ~/poznamky.txt'); }, check:m=>!(m.node(H+'/poznamky.txt').acl||[]).some(x=>x.k==='u' && x.n==='jana')},
{id:'umsk', ch:8, q:'Zobraz aktuálnu umask.', a:'umask', w:'0022 = nové súbory 644, adresáre 755.', check:m=>any(m,'umask')},
{id:'stat', ch:8, q:'Zobraz podrobnosti o <code>/etc/shadow</code>: práva číselne, vlastníka a časy.', a:'stat /etc/shadow', w:'stat ukáže aj Access (0000/----------).', check:m=>any(m,'stat',e=>arg(e,/shadow/))},

/* ---------- 9 procesy a výkon ---------- */
{id:'pgr', ch:9, q:'Zisti PID procesov <code>sshd</code> aj s ich príkazovým riadkom.', a:'pgrep -a sshd', w:'-a pridá celý príkaz, -l len meno.', check:m=>any(m,'pgrep',e=>arg(e,/sshd/))},
{id:'upt', ch:9, q:'Zisti, ako dlho server beží a aké je zaťaženie (load average).', a:'uptime', w:'Load porovnaj s počtom CPU (nproc).', check:m=>any(m,'uptime') || any(m,'w')},
{id:'nproc', ch:9, q:'Zisti počet CPU jadier.', a:'nproc', w:'Podrobne: lscpu.', check:m=>any(m,'nproc') || any(m,'lscpu')},
{id:'topb', ch:9, q:'Spusti <code>top</code> v dávkovom režime len na jeden výpis (napr. do logu).', a:'top -b -n 1', w:'-b batch, -n počet iterácií.', check:m=>L(m,'top').some(e=>e.flags.has('b') && (e.args.includes('1') || arg(e,/^-n1$/) || arg(e,/^-bn1$/)))},
{id:'kill', ch:9, q:'Proces <code>python3 /home/admin/zaseknuty.py</code> žerie CPU. Ukonči ho podľa mena (bez hľadania PID).', a:'pkill -f zaseknuty.py', w:'pkill/killall podľa mena, kill podľa PID. Predvolený signál je TERM (15).', setup:m=>{ m.procs.push({u:'admin',pid:4321,cpu:99.0,mem:0.4,stat:'R',cmd:'python3 /home/admin/zaseknuty.py'}); }, check:m=>!m.procs.some(p=>/zaseknuty/.test(p.cmd))},
{id:'kill9', ch:9, q:'Proces s PID <code>4321</code> nereaguje na bežné ukončenie. Ukonči ho natvrdo.', a:'kill -9 4321', w:'-9 = KILL, proces nemá šancu upratať. Najprv vždy skús kill PID (TERM).', setup:m=>{ m.procs.push({u:'admin',pid:4321,cpu:0.0,mem:0.4,stat:'D',cmd:'python3 /home/admin/zaseknuty.py'}); }, check:m=>(m.killed||[]).some(k=>k.pid===4321 && /^-(9|KILL|SIGKILL|s ?KILL)$/i.test(k.sig))},
{id:'psort', ch:9, q:'Vypíš procesy zoradené podľa využitia pamäte (najviac hore).', a:'ps aux --sort=-%mem', w:'--sort=-%cpu podľa CPU. Pridaj | head.', check:m=>L(m,'ps').some(e=>/--sort[= ]-?%?mem|--sort[= ]-rss/.test(e.args.join(' ')))},
{id:'dfi', ch:9, q:'Disk hlási „No space left“, ale <code>df -h</code> ukazuje voľné miesto. Skontroluj inody.', a:'df -i', w:'Milióny malých súborov minú inody skôr ako miesto.', check:m=>ran(m,'df',['i'])},
{id:'vmst', ch:9, q:'Vypíš štatistiky pamäte a CPU <code>vmstat</code> každú sekundu, 5-krát.', a:'vmstat 1 5', w:'Stĺpce si/so = swapovanie, wa = čakanie na disk.', check:m=>any(m,'vmstat',e=>e.args.includes('1') && e.args.includes('5'))},
{id:'freem', ch:9, q:'Zobraz pamäť v megabajtoch.', a:'free -m', w:'-h čitateľne, -m MiB, -g GiB.', check:m=>ran(m,'free',['m'])},
{id:'lsof', ch:9, q:'Zisti, ktoré súbory sú zmazané, ale stále otvorené procesom (zaberajú miesto).', a:'sudo lsof +L1', w:'Miesto uvoľníš reštartom procesu, ktorý ich drží.', setup:m=>asRoot(m,['dnf install -y lsof']), check:m=>any(m,'lsof',e=>arg(e,/^\+L1$/))},

/* ---------- 10 systemd ---------- */
{id:'srst', ch:10, q:'Reštartuj službu <code>chronyd</code>.', a:'sudo systemctl restart chronyd', w:'reload načíta konfiguráciu bez prerušenia (ak to služba vie).', check:m=>ran(m,'systemctl',[],e=>e.args[0]==='restart' && arg(e,/^chronyd/) && root(e))},
{id:'sdis', ch:10, q:'Zastav službu <code>cockpit</code> a zakáž jej štart pri boote jedným príkazom.', a:'sudo systemctl disable --now cockpit', w:'disable --now = stop + disable.', setup:m=>asRoot(m,['systemctl enable --now cockpit']), check:m=>!m.svc.cockpit.active && !m.svc.cockpit.enabled},
{id:'sisen', ch:10, q:'Zisti, či je služba <code>firewalld</code> povolená pri štarte (jedno slovo vo výstupe).', a:'systemctl is-enabled firewalld', w:'is-active zisťuje, či beží.', check:m=>ran(m,'systemctl',[],e=>e.args[0]==='is-enabled' && arg(e,/firewalld/))},
{id:'slu', ch:10, q:'Vypíš všetky bežiace služby.', a:'systemctl list-units --type=service --state=running', w:'Bez --state ukáže aj neaktívne načítané.', check:m=>L(m,'systemctl').some(e=>e.args[0]==='list-units' && arg(e,/service/)) || L(m,'systemctl').some(e=>e.args.includes('--type=service'))},
{id:'scat', ch:10, q:'Zobraz unit súbor služby <code>sshd</code> (aj s drop-in úpravami).', a:'systemctl cat sshd', w:'Ukáže, odkiaľ sa súbor načítal.', check:m=>ran(m,'systemctl',[],e=>e.args[0]==='cat' && arg(e,/sshd/))},
{id:'smask', ch:10, q:'Zabráň tomu, aby sa služba <code>nginx</code> dala spustiť (ani ručne, ani ako závislosť).', a:'sudo systemctl mask nginx', w:'mask = odkaz na /dev/null. Späť: unmask.', setup:m=>asRoot(m,['dnf install -y nginx']), check:m=>ran(m,'systemctl',[],e=>e.args[0]==='mask' && arg(e,/nginx/))},
{id:'jf', ch:10, q:'Sleduj žurnál naživo.', a:'journalctl -f', w:'Pre jednu službu: journalctl -fu sshd.', check:m=>ran(m,'journalctl',['f'])},
{id:'jsin', ch:10, q:'Zobraz žurnál služby <code>sshd</code> za poslednú hodinu.', a:'journalctl -u sshd --since "1 hour ago"', w:'--since/--until berú aj "today", "2026-11-01 08:00".', check:m=>L(m,'journalctl').some(e=>e.flags.has('u') && (e.flags.has('since') || e.flags.has('S')))},
{id:'sreld', ch:10, q:'Načítaj novú konfiguráciu <code>httpd</code> bez prerušenia spojení.', a:'sudo systemctl reload httpd', w:'reload pošle signál, služba nespadne.', setup:m=>asRoot(m,['dnf install -y httpd','systemctl start httpd']), check:m=>ran(m,'systemctl',[],e=>/^(reload|reload-or-restart)$/.test(e.args[0]) && arg(e,/httpd/))},
{id:'sgdef', ch:10, q:'Zisti predvolený cieľ (target), do ktorého server štartuje.', a:'systemctl get-default', w:'Server: multi-user.target, desktop: graphical.target.', check:m=>ran(m,'systemctl',[],e=>e.args[0]==='get-default')},

/* ---------- 11 balíky ---------- */
{id:'drm', ch:11, q:'Odinštaluj balík <code>tree</code>.', a:'sudo dnf remove -y tree', w:'dnf remove odstráni aj nepotrebné závislosti.', setup:m=>asRoot(m,['dnf install -y tree']), check:m=>!m.pkgs.has('tree')},
{id:'dsrch', ch:11, q:'Vyhľadaj v repozitároch balíky, ktoré súvisia s <code>nginx</code>.', a:'dnf search nginx', w:'search hľadá v mene a popise.', check:m=>ran(m,'dnf',[],e=>e.args[0]==='search' && arg(e,/nginx/))},
{id:'dinfo', ch:11, q:'Zobraz verziu, repozitár a popis balíka <code>httpd</code>.', a:'dnf info httpd', w:'Funguje aj pre nenainštalované balíky.', check:m=>ran(m,'dnf',[],e=>e.args[0]==='info' && arg(e,/httpd/))},
{id:'dli', ch:11, q:'Vypíš všetky nainštalované balíky cez dnf.', a:'dnf list --installed', w:'Alebo rpm -qa. Na RHEL 9 funguje aj dnf list installed.', check:m=>ran(m,'dnf',[],e=>e.args[0]==='list' && (arg(e,/installed/))) || ran(m,'rpm',['q','a'])},
{id:'rqa', ch:11, q:'Zisti cez rpm, či je nainštalovaný niektorý balík s <code>openssh</code> v mene.', a:'rpm -qa | grep openssh', w:'rpm -qa vypíše všetky balíky.', check:m=>ran(m,'rpm',['q','a']) && any(m,'grep',e=>arg(e,/openssh/))},
{id:'rql', ch:11, q:'Vypíš všetky súbory, ktoré nainštaloval balík <code>chrony</code>.', a:'rpm -ql chrony', w:'-l list. Pre konfiguráky -c, dokumentáciu -d.', check:m=>ran(m,'rpm',['q','l'],e=>arg(e,/chrony/))},
{id:'drep', ch:11, q:'Vypíš povolené repozitáre.', a:'dnf repolist', w:'dnf repolist all ukáže aj vypnuté.', check:m=>ran(m,'dnf',[],e=>e.args[0]==='repolist')},
{id:'dchk', ch:11, q:'Zisti, či sú k dispozícii aktualizácie (nič neinštaluj).', a:'dnf check-update', w:'Návratový kód 100 = aktualizácie existujú.', check:m=>L(m,'dnf').some(e=>e.args[0]==='check-update' || (e.args[0]==='updateinfo') || (e.args[0]==='list' && arg(e,/updates|upgrades/)))},
{id:'dundo', ch:11, q:'Vráť poslednú transakciu dnf.', a:'sudo dnf history undo last', w:'Alebo s číslom z dnf history.', setup:m=>asRoot(m,['dnf install -y tree']), check:m=>!m.pkgs.has('tree')},
{id:'dclean', ch:11, q:'Vymaž cache dnf (napr. keď repozitár hlási staré metadáta).', a:'sudo dnf clean all', w:'Potom dnf makecache.', check:m=>ran(m,'dnf',[],e=>e.args[0]==='clean')},
{id:'nrs', ch:11, q:'Po aktualizácii zisti, či treba reštartovať celý server.', a:'sudo dnf needs-restarting -r', w:'-r = reboot hint. Bez -r vypíše procesy so starými knižnicami.', check:m=>L(m,'dnf').some(e=>e.args[0]==='needs-restarting') || any(m,'needs-restarting')},
{id:'dup', ch:11, q:'Aktualizuj všetky balíky bez potvrdzovania.', a:'sudo dnf upgrade -y', w:'dnf update je alias. Na produkcii najprv check-update a snapshot.', check:m=>ran(m,'dnf',['y'],e=>e.args.some(a=>/^(upgrade|update)$/.test(a)) && root(e))},

/* ---------- 12 sieť ---------- */
{id:'nmcs', ch:12, q:'Vypíš profily pripojení NetworkManagera.', a:'nmcli con show', w:'con = connection. Aktívne: nmcli con show --active.', check:m=>any(m,'nmcli',e=>/^c(on(nection)?)?$/.test(e.args[0]) && (!e.args[1] || /^s(how)?$/.test(e.args[1])))},
{id:'nmds', ch:12, q:'Vypíš stav sieťových zariadení cez nmcli.', a:'nmcli device status', w:'dev = device.', check:m=>any(m,'nmcli',e=>/^d(ev(ice)?)?$/.test(e.args[0]))},
{id:'nmip', ch:12, q:'Nastav profilu <code>ens192</code> statickú IP <code>10.0.20.35/24</code> s ručným nastavením (bez DHCP).', a:'sudo nmcli con mod ens192 ipv4.addresses 10.0.20.35/24 ipv4.method manual', w:'Potom nmcli con up ens192. Pozor na vzdialené pripojenie.', check:m=>ran(m,'nmcli',[],e=>arg(e,/ipv4\.addresses/) && arg(e,/10\.0\.20\.35\/24/) && arg(e,/manual/))},
{id:'nmup', ch:12, q:'Aktivuj zmeny v profile <code>ens192</code>.', a:'sudo nmcli con up ens192', w:'Zmeny cez con mod sa prejavia až po up (alebo reštarte).', check:m=>ran(m,'nmcli',[],e=>e.args.includes('up') && arg(e,/ens192/))},
{id:'hnset', ch:12, q:'Nastav hostname servera natrvalo na <code>web03.firma.local</code>.', a:'sudo hostnamectl set-hostname web03.firma.local', w:'Zapíše do /etc/hostname.', check:m=>/web03/.test(m.hostname)},
{id:'ssn', ch:12, q:'Zobraz nadviazané TCP spojenia s číselnými adresami.', a:'ss -tn', w:'Bez -l ukáže nadviazané spojenia. -a všetky.', check:m=>L(m,'ss').some(e=>e.flags.has('t') && e.flags.has('n') && !e.flags.has('l'))},
{id:'ss22', ch:12, q:'Zisti, či niečo počúva na TCP porte 22 (len tento port).', a:"ss -tln 'sport = :22'", w:'Jednoduchšie: ss -tlnp | grep :22.', check:m=>(L(m,'ss').some(e=>e.flags.has('l') && e.flags.has('t')) && (any(m,'grep',e=>arg(e,/22/)) || L(m,'ss').some(e=>arg(e,/22/))))},
{id:'curlI', ch:12, q:'Zobraz len HTTP hlavičky odpovede z <code>http://localhost</code>.', a:'curl -I http://localhost', w:'-I HEAD požiadavka, -v podrobne, -k ignoruje certifikát.', setup:m=>asRoot(m,['dnf install -y httpd','systemctl start httpd']), check:m=>L(m,'curl').some(e=>(e.flags.has('I')||e.flags.has('head')) && arg(e,/localhost/))},
{id:'digs', ch:12, q:'Zisti cez DNS len IP adresu mena <code>db01.firma.local</code> (krátky výstup).', a:'dig +short db01.firma.local', w:'+short vypíše len odpoveď. dig je v balíku bind-utils.', setup:m=>asRoot(m,['dnf install -y bind-utils']), check:m=>any(m,'dig',e=>arg(e,/^\+short$/) && arg(e,/db01/))},
{id:'resolv', ch:12, q:'Zobraz, ktoré DNS servery systém práve používa (súbor).', a:'cat /etc/resolv.conf', w:'Generuje ho NetworkManager, ručne ho neupravuj.', check:m=>any(m,'cat',e=>arg(e,/resolv\.conf/))},
{id:'iplink', ch:12, q:'Zobraz sieťové rozhrania a ich stav (UP/DOWN) bez IP adries.', a:'ip link', w:'ip -br link je stručnejšie.', check:m=>L(m,'ip').some(e=>e.args.some(a=>/^l(ink)?$/.test(a)))},

/* ---------- 13 firewall ---------- */
{id:'fgaz', ch:13, q:'Zisti aktívne zóny firewallu a ich rozhrania.', a:'firewall-cmd --get-active-zones', w:'Predvolená: --get-default-zone.', check:m=>ran(m,'firewall-cmd',['get-active-zones'])},
{id:'fgdz', ch:13, q:'Zisti predvolenú zónu firewallu.', a:'firewall-cmd --get-default-zone', w:'Zmena: --set-default-zone=ZÓNA.', check:m=>ran(m,'firewall-cmd',['get-default-zone'])},
{id:'flsv', ch:13, q:'Vypíš len povolené služby v predvolenej zóne.', a:'firewall-cmd --list-services', w:'--list-ports pre porty.', check:m=>ran(m,'firewall-cmd',['list-services'])},
{id:'frun', ch:13, q:'Povoľ službu <code>http</code> len dočasne (do reštartu firewallu), na skúšku.', a:'sudo firewall-cmd --add-service=http', w:'Bez --permanent = len runtime. Ak funguje: --runtime-to-permanent.', check:m=>m.fw.runtime.public.services.includes('http') && !m.fw.perm.public.services.includes('http')},
{id:'fr2p', ch:13, q:'Pridal si pravidlá len do runtime a fungujú. Ulož aktuálny runtime stav natrvalo.', a:'sudo firewall-cmd --runtime-to-permanent', w:'Skopíruje runtime do permanent.', setup:m=>asRoot(m,['firewall-cmd --add-service=http']), check:m=>m.fw.perm.public.services.includes('http')},
{id:'frel', ch:13, q:'Pridal si pravidlo s <code>--permanent</code>. Načítaj ho, aby platilo hneď.', a:'sudo firewall-cmd --reload', w:'--reload zahodí runtime zmeny, ktoré nie sú permanent.', setup:m=>asRoot(m,['firewall-cmd --permanent --add-service=http']), check:m=>m.fw.runtime.public.services.includes('http')},
{id:'frp', ch:13, q:'Natrvalo zatvor port <code>8080/tcp</code>.', a:'sudo firewall-cmd --permanent --remove-port=8080/tcp', w:'Potom --reload.', setup:m=>asRoot(m,['firewall-cmd --permanent --add-port=8080/tcp','firewall-cmd --reload']), check:m=>!m.fw.perm.public.ports.includes('8080/tcp')},
{id:'fsrc', ch:13, q:'Natrvalo pridaj do zóny <code>internal</code> zdrojovú sieť <code>10.0.30.0/24</code>.', a:'sudo firewall-cmd --permanent --zone=internal --add-source=10.0.30.0/24', w:'Prevádzka z tejto siete potom ide cez pravidlá zóny internal.', check:m=>(m.fw.perm.internal.sources||[]).includes('10.0.30.0/24')},
{id:'frich', ch:13, q:'Natrvalo povoľ SSH len z adresy <code>10.0.20.15</code> rich rule pravidlom.', a:'sudo firewall-cmd --permanent --add-rich-rule=\'rule family="ipv4" source address="10.0.20.15" service name="ssh" accept\'', w:'Rich rules = podmienky (zdroj, služba, log, limit).', check:m=>(m.fw.perm.public.rich||[]).some(r=>/10\.0\.20\.15/.test(r) && /ssh/.test(r) && /accept/.test(r))},
{id:'flp', ch:13, q:'Vypíš len otvorené porty v predvolenej zóne.', a:'firewall-cmd --list-ports', w:'Služby (http, ssh) sa tu neukážu.', check:m=>ran(m,'firewall-cmd',['list-ports'])},

/* ---------- 14 SELinux ---------- */
{id:'sest', ch:14, q:'Zobraz podrobný stav SELinuxu (režim, politika, režim z configu).', a:'sestatus', w:'getenforce ukáže len režim.', check:m=>any(m,'sestatus')},
{id:'sperm', ch:14, q:'Prepni SELinux dočasne do režimu Permissive (na diagnostiku).', a:'sudo setenforce 0', w:'Platí do reštartu. Natrvalo cez /etc/selinux/config, ale vypínanie nie je riešenie.', check:m=>m.se.mode==='Permissive'},
{id:'senf', ch:14, q:'SELinux je v Permissive. Vráť ho do Enforcing (bez reštartu).', a:'sudo setenforce 1', w:'1 = Enforcing, 0 = Permissive.', setup:m=>asRoot(m,['setenforce 0']), check:m=>m.se.mode==='Enforcing'},
{id:'sfc', ch:14, q:'Natrvalo nastav kontext <code>httpd_sys_content_t</code> pre <code>/srv/web</code> a všetko v ňom (pravidlo v politike).', a:'sudo semanage fcontext -a -t httpd_sys_content_t "/srv/web(/.*)?"', w:'Potom restorecon -Rv /srv/web. chcon by reštart relabel zrušil.', setup:m=>asRoot(m,['dnf install -y policycoreutils-python-utils','mkdir /srv/web']), check:m=>ran(m,'semanage',[],e=>e.args[0]==='fcontext' && arg(e,/httpd_sys_content_t/) && arg(e,/\/srv\/web/))},
{id:'sgb', ch:14, q:'Vypíš všetky SELinux booleany, ktoré sa týkajú httpd.', a:'getsebool -a | grep httpd', w:'Alebo semanage boolean -l | grep httpd (aj s popisom).', check:m=>(ran(m,'getsebool',['a']) && any(m,'grep',e=>arg(e,/httpd/))) || (any(m,'semanage',e=>e.args[0]==='boolean') && any(m,'grep',e=>arg(e,/httpd/)))},
{id:'savc', ch:14, q:'Vypíš nedávne zamietnutia SELinuxu (AVC) z audit logu.', a:'sudo ausearch -m avc -ts recent', w:'-m typ správy, -ts čas (recent = posledných 10 min).', check:m=>any(m,'ausearch',e=>arg(e,/avc/i))},
{id:'spl', ch:14, q:'Zisti, ktoré porty smie používať apache podľa SELinuxu.', a:'sudo semanage port -l | grep http_port_t', w:'Nový port: semanage port -a -t http_port_t -p tcp PORT.', setup:m=>asRoot(m,['dnf install -y policycoreutils-python-utils']), check:m=>ran(m,'semanage',['l'],e=>e.args[0]==='port') && (any(m,'grep',e=>arg(e,/http/)) || true)},
{id:'sa2w', ch:14, q:'Pošli posledné AVC zamietnutia do nástroja, ktorý vysvetlí ich príčinu.', a:'sudo ausearch -m avc -ts recent | audit2why', w:'audit2why povie, či pomôže boolean alebo kontext.', check:m=>any(m,'audit2why') || any(m,'sealert')},
{id:'lsZd', ch:14, q:'Zobraz SELinux kontext samotného adresára <code>/var/www/html</code>.', a:'ls -Zd /var/www/html', w:'-d = adresár ako položka.', setup:m=>asRoot(m,['dnf install -y httpd']), check:m=>ran(m,'ls',['Z','d'],e=>arg(e,/var\/www\/html/))},

/* ---------- 15 disky a LVM ---------- */
{id:'pvc', ch:15, q:'Priprav disk <code>/dev/sdb</code> pre LVM (fyzický zväzok).', a:'sudo pvcreate /dev/sdb', w:'Potom vgcreate alebo vgextend.', check:m=>!!m.lvm.pvs['/dev/sdb']},
{id:'vgc', ch:15, q:'Vytvor skupinu zväzkov <code>data</code> z disku <code>/dev/sdb</code>.', a:'sudo vgcreate data /dev/sdb', w:'vgcreate MENO DISKY…', setup:m=>asRoot(m,['pvcreate /dev/sdb']), check:m=>!!m.lvm.vgs.data},
{id:'lvc', ch:15, q:'Vytvor v skupine <code>data</code> logický zväzok <code>app</code> s veľkosťou 5G.', a:'sudo lvcreate -n app -L 5G data', w:'-n meno, -L veľkosť, -l 100%FREE celé voľné miesto.', setup:m=>asRoot(m,['pvcreate /dev/sdb','vgcreate data /dev/sdb']), check:m=>!!m.lvm.lvs['data/app']},
{id:'mkx', ch:15, q:'Vytvor súborový systém XFS na <code>/dev/data/app</code>.', a:'sudo mkfs.xfs /dev/data/app', w:'RHEL predvolene používa XFS. ext4: mkfs.ext4.', setup:m=>asRoot(m,['pvcreate /dev/sdb','vgcreate data /dev/sdb','lvcreate -n app -L 5G data']), check:m=>(m.lvm.lvs['data/app']||{}).fs==='xfs'},
{id:'mnt', ch:15, q:'Pripoj <code>/dev/data/app</code> do <code>/srv/app</code> (adresár už existuje), zatiaľ len dočasne.', a:'sudo mount /dev/data/app /srv/app', w:'Natrvalo: riadok v /etc/fstab, potom mount -a.', setup:m=>asRoot(m,['pvcreate /dev/sdb','vgcreate data /dev/sdb','lvcreate -n app -L 5G data','mkfs.xfs /dev/data/app','mkdir /srv/app']), check:m=>m.mounts.some(x=>x.dir==='/srv/app')},
{id:'blkid', ch:15, q:'Zisti UUID všetkých blokových zariadení (do fstab).', a:'sudo blkid', w:'Alebo lsblk -f.', check:m=>any(m,'blkid') || ran(m,'lsblk',['f'])},
{id:'vgs', ch:15, q:'Zisti, koľko voľného miesta je v skupinách zväzkov.', a:'sudo vgs', w:'Stĺpec VFree. pvs a lvs pre disky a zväzky.', check:m=>any(m,'vgs') || any(m,'vgdisplay')},
{id:'lvs', ch:15, q:'Vypíš logické zväzky a ich veľkosti.', a:'sudo lvs', w:'lvdisplay je podrobnejší.', check:m=>any(m,'lvs') || any(m,'lvdisplay')},
{id:'swps', ch:15, q:'Zobraz aktívny swap.', a:'swapon --show', w:'Alebo free -h (riadok Swap).', check:m=>any(m,'swapon') || ran(m,'free')},
{id:'fmv', ch:15, q:'Over syntax <code>/etc/fstab</code> bez pripájania.', a:'sudo findmnt --verify', w:'Odhalí preklepy v UUID a typoch.', check:m=>ran(m,'findmnt',['verify'])},
{id:'vgx', ch:15, q:'Pridaj disk <code>/dev/sdb</code> (už je PV) do existujúcej skupiny <code>rhel</code>.', a:'sudo vgextend rhel /dev/sdb', w:'Potom môžeš zväčšiť LV cez lvextend -r.', setup:m=>asRoot(m,['pvcreate /dev/sdb']), check:m=>(m.lvm.pvs['/dev/sdb']||{}).vg==='rhel'},

/* ---------- 16 SSH a archívy ---------- */
{id:'sshc', ch:16, q:'Skopíruj svoj verejný kľúč na server <code>web02.firma.local</code> pre používateľa admin.', a:'ssh-copy-id admin@web02.firma.local', w:'Pridá kľúč do ~/.ssh/authorized_keys na cieli.', setup:m=>m.run('ssh-keygen -t ed25519 -N "" -f ~/.ssh/id_ed25519'), check:m=>any(m,'ssh-copy-id',e=>arg(e,/web02/))},
{id:'sshp', ch:16, q:'Pripoj sa cez SSH na <code>db01.firma.local</code>, ktorý počúva na porte 2222.', a:'ssh -p 2222 admin@db01.firma.local', w:'scp používa veľké -P.', check:m=>L(m,'ssh').some(e=>(e.args.includes('2222')||arg(e,/^-p2222$/)) && arg(e,/db01/))},
{id:'scp1', ch:16, q:'Skopíruj <code>~/poznamky.txt</code> na <code>web02.firma.local</code> do <code>/tmp</code>.', a:'scp ~/poznamky.txt admin@web02.firma.local:/tmp/', w:'Formát cieľa: [user@]host:cesta.', check:m=>any(m,'scp',e=>arg(e,/poznamky/) && arg(e,/web02[^:]*:\/tmp/))},
{id:'rsync', ch:16, q:'Zosynchronizuj adresár <code>~/skripty/</code> do <code>/srv/zaloha/skripty/</code> so zachovaním práv a s výpisom.', a:'sudo rsync -av ~/skripty/ /srv/zaloha/skripty/', w:'-a archív (práva, časy, rekurzia), -v výpis. Lomka na konci zdroja = obsah.', setup:m=>asRoot(m,['mkdir -p /srv/zaloha']), check:m=>ran(m,'rsync',['a'])},
{id:'tarx', ch:16, q:'Rozbaľ <code>~/stiahnute/appka-2.0.tar.gz</code> do <code>/tmp</code>.', a:'tar -xzf ~/stiahnute/appka-2.0.tar.gz -C /tmp', w:'-x rozbaľ, -C cieľový adresár.', check:m=>m.exists('/tmp/appka-2.0')},
{id:'tarj', ch:16, q:'Zabaľ <code>/etc/ssh</code> do archívu <code>/tmp/ssh.tar.gz</code> ako root (so zachovaním práv).', a:'sudo tar -czpf /tmp/ssh.tar.gz /etc/ssh', w:'-p zachová práva pri rozbaľovaní. Root vidí aj súbory 600.', check:m=>m.exists('/tmp/ssh.tar.gz') && ran(m,'tar',['c'],root)},
{id:'gz', ch:16, q:'Skomprimuj súbor <code>~/logy/app.log</code> cez gzip.', a:'gzip ~/logy/app.log', w:'Vznikne app.log.gz, pôvodný súbor zmizne. gunzip ho vráti.', check:m=>m.exists(H+'/logy/app.log.gz')},
{id:'sshT', ch:16, q:'Zisti, aká je skutočná výsledná hodnota <code>PermitRootLogin</code> v sshd (po všetkých konfigurákoch).', a:'sudo sshd -T | grep -i permitrootlogin', w:'sshd -T vypíše efektívnu konfiguráciu.', check:m=>ran(m,'sshd',['T'])},
{id:'kgf', ch:16, q:'Vygeneruj kľúč ed25519 do súboru <code>~/.ssh/deploy</code> bez hesla.', a:'ssh-keygen -t ed25519 -f ~/.ssh/deploy -N ""', w:'-f súbor, -N heslo (prázdne). Na automatizáciu.', check:m=>m.exists(H+'/.ssh/deploy') && m.exists(H+'/.ssh/deploy.pub')},

/* ---------- 17 logy a cron ---------- */
{id:'logger', ch:17, q:'Zapíš do systémového logu správu <code>test zálohy</code>.', a:'logger "test zálohy"', w:'Hodí sa v skriptoch. -t nastaví značku.', check:m=>any(m,'logger',e=>arg(e,/test/))},
{id:'crada', ch:17, q:'Pridaj si do crontabu úlohu: každý deň o 2:30 spusti <code>/home/admin/skripty/zaloha.sh</code> (bez editora).', a:'(crontab -l; echo "30 2 * * * /home/admin/skripty/zaloha.sh") | crontab -', w:'Poradie: minúta hodina deň mesiac deň_týždňa. Interaktívne: crontab -e.', check:m=>/^\s*30\s+2\s+\*\s+\*\s+\*\s+\S*zaloha\.sh/m.test((m.crontabs||{}).admin||'')},
{id:'tzset', ch:17, q:'Nastav časové pásmo servera na <code>Europe/Bratislava</code>.', a:'sudo timedatectl set-timezone Europe/Bratislava', w:'Zoznam: timedatectl list-timezones.', check:m=>ran(m,'timedatectl',[],e=>e.args[0]==='set-timezone' && arg(e,/Europe\/Bratislava/))},
{id:'chrs', ch:17, q:'Zobraz NTP zdroje, s ktorými sa server synchronizuje.', a:'chronyc sources', w:'* pred zdrojom = práve používaný. chronyc tracking ukáže odchýlku.', check:m=>any(m,'chronyc',e=>/^(sources|tracking)$/.test(e.args[0]))},
{id:'last', ch:17, q:'Zobraz históriu prihlásení na server.', a:'last', w:'lastb ukáže neúspešné (root). who/w kto je prihlásený teraz.', check:m=>any(m,'last')},
{id:'who', ch:17, q:'Zisti, kto je práve prihlásený a čo robí.', a:'w', w:'who je stručnejší.', check:m=>any(m,'w') || any(m,'who')},
{id:'jtd', ch:17, q:'Zobraz žurnál od dnešnej polnoci.', a:'journalctl --since today', w:'--since yesterday, "2026-11-01 08:00".', check:m=>L(m,'journalctl').some(e=>(e.flags.has('since')||e.flags.has('S')) && arg(e,/today/))},
{id:'secure', ch:17, q:'Zobraz posledné záznamy logu prihlásení a sudo (<code>/var/log/secure</code>).', a:'sudo tail /var/log/secure', w:'Hľadaj Failed password, sudo: … COMMAND=.', check:m=>any(m,'tail',e=>arg(e,/secure/)) || any(m,'less',e=>arg(e,/secure/)) || any(m,'grep',e=>arg(e,/secure/))},

/* ---------- 18 inštalácia produktov ---------- */
{id:'rimp', ch:18, q:'Importuj GPG kľúč dodávateľa <code>~/stiahnute/RPM-GPG-KEY-acme</code>.', a:'sudo rpm --import ~/stiahnute/RPM-GPG-KEY-acme', w:'Potom rpm -K hlási digests signatures OK.', check:m=>ran(m,'rpm',['import'],root)},
{id:'repo', ch:18, q:'Pridaj repozitár dodávateľa: skopíruj <code>~/stiahnute/acme.repo</code> na správne miesto.', a:'sudo cp ~/stiahnute/acme.repo /etc/yum.repos.d/', w:'Alebo dnf config-manager --add-repo URL.', check:m=>m.isFile('/etc/yum.repos.d/acme.repo')},
{id:'rqpl', ch:18, q:'Pozri, aké súbory obsahuje balík <code>~/stiahnute/acme-agent-3.2.1-1.el9.x86_64.rpm</code>, bez inštalácie.', a:'rpm -qpl ~/stiahnute/acme-agent-3.2.1-1.el9.x86_64.rpm', w:'-p = pracuj so súborom balíka, nie s databázou.', check:m=>ran(m,'rpm',['q','p','l'])},
{id:'rqpi', ch:18, q:'Pozri informácie (verzia, dodávateľ, popis) v súbore <code>~/stiahnute/acme-agent-3.2.1-1.el9.x86_64.rpm</code> bez inštalácie.', a:'rpm -qpi ~/stiahnute/acme-agent-3.2.1-1.el9.x86_64.rpm', w:'-i info.', check:m=>ran(m,'rpm',['q','p','i'])},
{id:'rqi', ch:18, q:'Zobraz informácie o nainštalovanom balíku <code>acme-agent</code>.', a:'rpm -qi acme-agent', w:'Alebo dnf info acme-agent.', setup:m=>asRoot(m,['rpm --import /home/admin/stiahnute/RPM-GPG-KEY-acme','dnf install -y /home/admin/stiahnute/acme-agent-3.2.1-1.el9.x86_64.rpm']), check:m=>ran(m,'rpm',['q','i'],e=>arg(e,/acme-agent/)) || ran(m,'dnf',[],e=>e.args[0]==='info' && arg(e,/acme/))},
{id:'optx', ch:18, q:'Rozbaľ aplikáciu <code>~/stiahnute/appka-2.0.tar.gz</code> do <code>/opt</code>.', a:'sudo tar -xzf ~/stiahnute/appka-2.0.tar.gz -C /opt', w:'Aplikácie mimo RPM idú do /opt. Konfigurák často do /etc/opt alebo /opt/app/etc.', check:m=>m.exists('/opt/appka-2.0')},
{id:'jv', ch:18, q:'Zisti verziu Javy, ktorú produkt použije.', a:'java -version', w:'Jedna pomlčka. Viac verzií: alternatives --config java.', setup:m=>asRoot(m,['dnf install -y java-17-openjdk-headless']), check:m=>any(m,'java')},
{id:'pgi', ch:18, q:'Nainštaloval si <code>postgresql-server</code>. Inicializuj databázový klaster.', a:'sudo postgresql-setup --initdb', w:'Potom systemctl enable --now postgresql.', setup:m=>asRoot(m,['dnf install -y postgresql-server']), check:m=>any(m,'postgresql-setup',e=>arg(e,/initdb/))},

/* ---------- 19 bash skripty ---------- */
{id:'bshn', ch:19, q:'Skontroluj syntax skriptu <code>~/skripty/kontrola.sh</code> bez spustenia.', a:'bash -n ~/skripty/kontrola.sh', w:'-n = noexec. -x vypisuje príkazy počas behu (ladenie).', check:m=>ran(m,'bash',['n'],e=>arg(e,/kontrola/))},
{id:'bshx', ch:19, q:'Spusti skript <code>~/skripty/kontrola.sh</code> v režime ladenia (každý príkaz sa vypíše pred spustením).', a:'bash -x ~/skripty/kontrola.sh', w:'Alebo set -x vo vnútri skriptu.', check:m=>ran(m,'bash',['x'],e=>arg(e,/kontrola/))},
{id:'xrun', ch:19, q:'Sprav <code>~/skripty/kontrola.sh</code> spustiteľným a spusti ho cez cestu.', a:'chmod +x ~/skripty/kontrola.sh && ~/skripty/kontrola.sh', w:'./skript alebo celá cesta. Samotné meno nestačí (aktuálny adresár nie je v PATH).', check:m=>!!(m.node(H+'/skripty/kontrola.sh').m & 0o100) && m.log.some(e=>/kontrola\.sh$/.test(e.name)) && any(m,'echo',e=>arg(e,/Kontrola/))},
{id:'rc', ch:19, q:'Zisti návratový kód posledného príkazu.', a:'echo $?', w:'0 = úspech, iné = chyba.', check:m=>m.history.some(h=>/echo\s+"?\$\?"?/.test(h))},
{id:'var', ch:19, q:'Ulož do premennej <code>DNES</code> dnešný dátum vo formáte RRRR-MM-DD.', a:'DNES=$(date +%F)', w:'$( ) vloží výstup príkazu. Bez medzier okolo =.', check:m=>/^\d{4}-\d{2}-\d{2}$/.test((m.env||{}).DNES || (m.vars||{}).DNES || '') },
{id:'testf', ch:19, q:'Jedným riadkom: ak existuje súbor <code>/etc/fstab</code>, vypíš <code>OK</code>.', a:'[ -f /etc/fstab ] && echo OK', w:'-f súbor, -d adresár, -e čokoľvek. && = len pri úspechu.', check:m=>m.history.some(h=>/(\[|test)\s+-[fe]\s+\/etc\/fstab/.test(h)) && any(m,'echo',e=>arg(e,/^OK$/))},
{id:'seq', ch:19, q:'Vypíš čísla 1 až 5 cyklom for a príkazom <code>seq</code>.', a:'for i in $(seq 1 5); do echo $i; done', w:'Alebo for i in {1..5}.', check:m=>L(m,'echo').filter(e=>/^[1-5]$/.test(e.args[0]||'')).length>=5 && m.history.some(h=>/\bfor\b/.test(h))},
{id:'expo', ch:19, q:'Nastav premennú prostredia <code>EDITOR</code> na <code>vim</code> tak, aby ju videli aj spúšťané programy.', a:'export EDITOR=vim', w:'Natrvalo: riadok do ~/.bashrc.', check:m=>(((m.env||{}).EDITOR)||'')==='vim' && any(m,'export')},
{id:'shb', ch:19, q:'Aký prvý riadok má mať bash skript? Zapíš ho do nového súboru <code>~/skripty/novy.sh</code>.', a:'echo "#!/bin/bash" > ~/skripty/novy.sh', w:'Shebang určí interpreter.', check:m=>/^#!\s*\/(usr\/)?bin\/(env\s+)?bash/.test(txt(m,H+'/skripty/novy.sh'))},

/* ---------- 20 boot a záchrana ---------- */
{id:'sdef', ch:20, q:'Nastav, aby server štartoval bez grafiky (textový režim) natrvalo.', a:'sudo systemctl set-default multi-user.target', w:'graphical.target pre desktop.', check:m=>ran(m,'systemctl',[],e=>e.args[0]==='set-default' && arg(e,/multi-user/))},
{id:'grdk', ch:20, q:'Zisti, ktoré jadro sa spustí ako predvolené.', a:'sudo grubby --default-kernel', w:'--set-default=CESTA zmení predvolené jadro.', check:m=>ran(m,'grubby',['default-kernel'])},
{id:'grinfo', ch:20, q:'Vypíš všetky záznamy zavádzača (jadrá a ich parametre).', a:'sudo grubby --info=ALL', w:'Záznamy sú v /boot/loader/entries/.', check:m=>L(m,'grubby').some(e=>e.flags.has('info'))},
{id:'grrm', ch:20, q:'Odober zo všetkých jadier parameter <code>rhgb</code> (aby bolo vidno hlásenia pri štarte).', a:'sudo grubby --update-kernel=ALL --remove-args="rhgb"', w:'--args pridá, --remove-args odoberie.', check:m=>!/(^| )rhgb( |$)/.test(m.grub.args) && ran(m,'grubby',['remove-args'])},
{id:'lboot', ch:20, q:'Vypíš zoznam štartov systému, ktoré si žurnál pamätá.', a:'journalctl --list-boots', w:'Log predošlého štartu: journalctl -b -1 (ak je žurnál trvalý).', check:m=>ran(m,'journalctl',['list-boots'])},
{id:'jb1', ch:20, q:'Zobraz chyby z <b>predošlého</b> štartu systému.', a:'journalctl -b -1 -p err', w:'Funguje len s trvalým žurnálom (/var/log/journal).', check:m=>L(m,'journalctl').some(e=>arg(e,/^-1$/) || arg(e,/^-b-1$/))},
{id:'jpers', ch:20, q:'Zapni trvalé ukladanie žurnálu: vytvor adresár, ktorý na to systemd potrebuje.', a:'sudo mkdir -p /var/log/journal', w:'Potom systemctl restart systemd-journald. Alebo Storage=persistent v journald.conf.', check:m=>m.isDir('/var/log/journal')},
{id:'drac', ch:20, q:'Pregeneruj initramfs pre aktuálne jadro.', a:'sudo dracut -f', w:'Treba po zmene ovládačov disku alebo LVM v initramfs.', check:m=>ran(m,'dracut',['f'])},

/* ---------- 21 Ansible ---------- */
{id:'ansv', ch:21, q:'Zisti verziu Ansible a cestu ku konfiguračnému súboru.', a:'ansible --version', w:'Riadok config file = … ukáže, ktorý ansible.cfg sa použil.', setup:m=>asRoot(m,['dnf install -y ansible-core']), check:m=>ran(m,'ansible',['version'])},
{id:'ansg', ch:21, q:'Zobraz skupiny a servery z inventára <code>~/ansible/inventory.example</code> ako strom.', a:'ansible-inventory -i ~/ansible/inventory.example --graph', w:'--list vypíše JSON.', setup:m=>asRoot(m,['dnf install -y ansible-core']), check:m=>ran(m,'ansible-inventory',['graph'])},
{id:'ansd', ch:21, q:'Zobraz dokumentáciu modulu <code>ansible.builtin.dnf</code>.', a:'ansible-doc ansible.builtin.dnf', w:'Príklady sú na konci. Zoznam modulov: ansible-doc -l.', setup:m=>asRoot(m,['dnf install -y ansible-core']), check:m=>any(m,'ansible-doc',e=>arg(e,/dnf/))},
{id:'ansu', ch:21, q:'Spusti na všetkých serveroch z <code>~/ansible/inventory.example</code> príkaz <code>uptime</code>.', a:'ansible all -i ~/ansible/inventory.example -m command -a uptime', w:'command je predvolený modul, -m môžeš vynechať.', setup:m=>asRoot(m,['dnf install -y ansible-core']), check:m=>ran(m,'ansible',[],e=>arg(e,/uptime/) && e.args.includes('-i'))},
{id:'anss', ch:21, q:'Over len syntax playbooku <code>~/ansible/web.yml</code>.', a:'ansible-playbook ~/ansible/web.yml --syntax-check', w:'Nespojí sa so žiadnym serverom.', setup:m=>{ asRoot(m,['dnf install -y ansible-core']); m.run(' ansible-galaxy collection install ansible.posix'); }, check:m=>ran(m,'ansible-playbook',['syntax-check'])},
{id:'ansl', ch:21, q:'Spusti playbook <code>~/ansible/web.yml</code> s inventárom <code>~/ansible/inventory.example</code> len na <code>web01.firma.local</code>.', a:'ansible-playbook -i ~/ansible/inventory.example ~/ansible/web.yml --limit web01.firma.local', w:'--limit (-l) obmedzí servery.', setup:m=>{ asRoot(m,['dnf install -y ansible-core']); m.run(' ansible-galaxy collection install ansible.posix'); }, check:m=>L(m,'ansible-playbook').some(e=>e.flags.has('limit')||e.flags.has('l'))},
{id:'ansb', ch:21, q:'Cez Ansible (ad-hoc) nainštaluj balík <code>tree</code> na skupinu <code>web</code> z <code>~/ansible/inventory.example</code>.', a:'ansible web -i ~/ansible/inventory.example -m ansible.builtin.dnf -a "name=tree state=present" -b', w:'-b = become (sudo). Bez neho zlyhá.', setup:m=>asRoot(m,['dnf install -y ansible-core']), check:m=>ran(m,'ansible',['b'],e=>arg(e,/dnf|package|yum/) && arg(e,/tree/))},
{id:'ansgl', ch:21, q:'Vypíš nainštalované Ansible kolekcie.', a:'ansible-galaxy collection list', w:'ansible-core má zabudované len ansible.builtin.', setup:m=>{ asRoot(m,['dnf install -y ansible-core']); m.run(' ansible-galaxy collection install ansible.posix'); }, check:m=>any(m,'ansible-galaxy',e=>e.args[0]==='collection' && e.args[1]==='list')},

/* ---------- 22 Podman ---------- */
{id:'podps', ch:22, q:'Vypíš bežiace kontajnery.', a:'podman ps', w:'-a aj zastavené.', setup:m=>asRoot(m,['dnf install -y container-tools']), check:m=>any(m,'podman',e=>e.args[0]==='ps')},
{id:'podpa', ch:22, q:'Vypíš všetky kontajnery vrátane zastavených.', a:'podman ps -a', w:'Zastavené zmažeš podman rm.', setup:m=>asRoot(m,['dnf install -y container-tools']), check:m=>ran(m,'podman',['a'],e=>e.args[0]==='ps') || ran(m,'podman',['all'],e=>e.args[0]==='ps')},
{id:'podi', ch:22, q:'Vypíš stiahnuté obrazy (images).', a:'podman images', w:'Mazanie: podman rmi.', setup:m=>asRoot(m,['dnf install -y container-tools']), check:m=>any(m,'podman',e=>e.args[0]==='images' || (e.args[0]==='image' && /^(ls|list)$/.test(e.args[1])))},
{id:'podpl', ch:22, q:'Stiahni obraz <code>registry.access.redhat.com/ubi9/ubi-minimal</code>.', a:'podman pull registry.access.redhat.com/ubi9/ubi-minimal', w:'Vždy uvádzaj celé meno s registrom.', setup:m=>asRoot(m,['dnf install -y container-tools']), check:m=>any(m,'podman',e=>e.args[0]==='pull' && arg(e,/ubi-minimal/))},
{id:'podlg', ch:22, q:'Zobraz logy kontajnera <code>web</code>.', a:'podman logs web', w:'-f sleduje naživo.', setup:m=>{ asRoot(m,['dnf install -y container-tools']); m.run('podman run -d --name web -p 8080:8080 registry.access.redhat.com/ubi9/httpd-24'); }, check:m=>any(m,'podman',e=>e.args[0]==='logs' && arg(e,/^web$/))},
{id:'podst', ch:22, q:'Zastav kontajner <code>web</code>.', a:'podman stop web', w:'Spustenie späť: podman start web.', setup:m=>{ asRoot(m,['dnf install -y container-tools']); m.run('podman run -d --name web -p 8080:8080 registry.access.redhat.com/ubi9/httpd-24'); }, check:m=>any(m,'podman',e=>e.args[0]==='stop' && arg(e,/^web$/))},
{id:'podrm', ch:22, q:'Zmaž kontajner <code>web</code> (aj keď beží) jedným príkazom.', a:'podman rm -f web', w:'-f zastaví a zmaže.', setup:m=>{ asRoot(m,['dnf install -y container-tools']); m.run('podman run -d --name web -p 8080:8080 registry.access.redhat.com/ubi9/httpd-24'); }, check:m=>any(m,'podman',e=>e.args[0]==='rm' && arg(e,/^web$/))},
{id:'podex', ch:22, q:'Spusti interaktívny shell v bežiacom kontajneri <code>web</code>.', a:'podman exec -it web /bin/bash', w:'-i interaktívne, -t terminál. V minimal obrazoch použi /bin/sh.', setup:m=>{ asRoot(m,['dnf install -y container-tools']); m.run('podman run -d --name web -p 8080:8080 registry.access.redhat.com/ubi9/httpd-24'); }, check:m=>L(m,'podman').some(e=>e.args[0]==='exec' && arg(e,/^web$/))},
{id:'podv', ch:22, q:'Spusti na pozadí kontajner <code>web2</code> z <code>registry.access.redhat.com/ubi9/httpd-24</code> s adresárom <code>~/web</code> pripojeným do <code>/var/www/html</code> so správnym SELinux kontextom.', a:'podman run -d --name web2 -v ~/web:/var/www/html:Z registry.access.redhat.com/ubi9/httpd-24', w:':Z nastaví SELinux kontext pre tento kontajner. Bez neho Permission denied.', setup:m=>{ asRoot(m,['dnf install -y container-tools']); m.run('mkdir ~/web'); }, check:m=>any(m,'podman',e=>e.args[0]==='run' && arg(e,/:\/var\/www\/html:Z$/))},

/* ---------- 23 výkon a upgrade ---------- */
{id:'tdl', ch:23, q:'Vypíš dostupné tuned profily.', a:'tuned-adm list', w:'Aktívny je označený na konci výpisu.', check:m=>any(m,'tuned-adm',e=>e.args[0]==='list')},
{id:'tdr', ch:23, q:'Zisti, ktorý tuned profil systém odporúča.', a:'tuned-adm recommend', w:'Podľa toho, či je to VM, fyzický server…', check:m=>any(m,'tuned-adm',e=>e.args[0]==='recommend')},
{id:'tdp', ch:23, q:'Nastav tuned profil <code>throughput-performance</code>.', a:'sudo tuned-adm profile throughput-performance', w:'Pre DB servery býva ešte vhodnejší špecifický profil od dodávateľa.', check:m=>/throughput-performance/.test(JSON.stringify(m.tuned))},
{id:'sysp', ch:23, q:'Nastav natrvalo <code>vm.swappiness = 10</code>: vytvor súbor <code>/etc/sysctl.d/90-swap.conf</code> a načítaj ho.', a:'echo "vm.swappiness = 10" | sudo tee /etc/sysctl.d/90-swap.conf && sudo sysctl --system', w:'sysctl -p SÚBOR načíta jeden súbor, --system všetky.', check:m=>/vm\.swappiness\s*=\s*10/.test(txt(m,'/etc/sysctl.d/90-swap.conf')) && m.sysctl['vm.swappiness']==='10'},
{id:'sysr', ch:23, q:'Zisti aktuálnu hodnotu <code>net.ipv4.ip_forward</code>.', a:'sysctl net.ipv4.ip_forward', w:'sysctl -a vypíše všetky. Hodnoty sú aj v /proc/sys/.', check:m=>any(m,'sysctl',e=>arg(e,/net\.ipv4\.ip_forward$/))},
{id:'iost', ch:23, q:'Zobraz rozšírené štatistiky diskov (vyťaženie, čakanie) každé 2 sekundy.', a:'iostat -x 2', w:'Stĺpec %util a await. Balík sysstat.', setup:m=>asRoot(m,['dnf install -y sysstat']), check:m=>ran(m,'iostat',['x'])},
{id:'sar', ch:23, q:'Zobraz históriu vyťaženia CPU zo sar (dnešok).', a:'sar -u', w:'sar -r pamäť, -d disky. Zbiera sysstat každých 10 minút.', setup:m=>asRoot(m,['dnf install -y sysstat']), check:m=>any(m,'sar')},
{id:'lpre', ch:23, q:'Spusti predupgradovú analýzu na RHEL 10.', a:'sudo leapp preupgrade', w:'Report: /var/log/leapp/leapp-report.txt. Inhibítory treba vyriešiť.', setup:m=>asRoot(m,['dnf install -y leapp-upgrade-el9toel10']), check:m=>any(m,'leapp',e=>e.args[0]==='preupgrade')},
{id:'mpst', ch:23, q:'Zobraz vyťaženie každého CPU zvlášť.', a:'mpstat -P ALL', w:'Ukáže, či jedno jadro nie je na 100 %.', setup:m=>asRoot(m,['dnf install -y sysstat']), check:m=>any(m,'mpstat')},

/* ---------- 24 RHEL 9 vs 10 ---------- */
{id:'r10rel', ch:24, ver:10, q:'Si na novom serveri. Over, že beží RHEL 10, a zisti presnú verziu.', a:'cat /etc/redhat-release', w:'Alebo hostnamectl, cat /etc/os-release.', check:m=>any(m,'cat',e=>arg(e,/redhat-release|os-release/)) || any(m,'hostnamectl')},
{id:'r10boot', ch:24, ver:10, q:'Zisti, či server beží v image mode (bootc) a aký obraz používa.', a:'sudo bootc status', w:'Na bežnom (package mode) serveri ti povie, že nie je bootc systém.', check:m=>any(m,'bootc',e=>e.args[0]==='status') || L(m,'bootc').some(e=>e.args[0]==='status')},
{id:'r9mod', ch:24, q:'Na RHEL 9 vypíš dostupné moduly (alternatívne verzie aplikácií).', a:'dnf module list', w:'RHEL 10 moduly nepoužíva, verzie sú bežné balíky.', check:m=>ran(m,'dnf',[],e=>e.args[0]==='module' && e.args[1]==='list')},
{id:'r10ver', ch:24, ver:10, q:'Zisti verziu jadra na RHEL 10 serveri.', a:'uname -r', w:'RHEL 10 má jadro 6.12, RHEL 9 5.14.', check:m=>ran(m,'uname',['r']) || ran(m,'uname',['a'])}
);
})();
